query IssueEdits($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    nameWithOwner
    issue(number: $number) {
      number updatedAt lastEditedAt
      timelineItems(itemTypes: [ISSUE_TYPE_ADDED_EVENT, ISSUE_TYPE_CHANGED_EVENT, ISSUE_TYPE_REMOVED_EVENT], first: 100) {
        pageInfo { hasNextPage }
        nodes {
          __typename
          ... on IssueTypeAddedEvent { createdAt issueType { name } }
          ... on IssueTypeChangedEvent { createdAt prevIssueType { name } issueType { name } }
          ... on IssueTypeRemovedEvent { createdAt issueType { name } }
        }
      }
    }
  }
}

